-- GoTripMaldives / Yuvi Blue Maldives (Himmafushi): replaces the 9 earlier
-- Himmafushi packages (20261001006700_yuviblue_himmafushi.sql and later
-- fixes) with 16 real packages built directly from the owner-supplied
-- "Gotripmaldives Customer Holiday Rates.pdf" (Diving/Surfing/Honeymoon/
-- Family Holiday panels, each with 4 real duration tiers: 2/4/5/6 nights).
-- Per the owner's explicit instruction, Fishing Holiday packages are NOT
-- built from this PDF — those come from the separate Fishing Rate Sheet
-- (see 20261020000300_gotrip_mfh_pricing_update.sql, Maamendhoo/Gaafu
-- Alifu Atoll, a separate GoTripMaldives/Yuvi Blue location).
--
-- Every price below is this PDF's own "Final Selling Price Per Couple"
-- figure — already a customer-facing retail price, no markup applied
-- (unlike the original partner-contract-sourced migration, this document
-- is titled "Customer Holiday Rates" and is already final pricing).
-- Family Holiday packages are priced per the PDF's own "Child Age 2+"
-- column (a family room for 2 adults + 1 child, 3 paying guests) since
-- the PDF never shows a bare 2-adult total for this theme — price_type
-- 'per-package', not 'per-couple'.

-- Remove the 9 superseded Himmafushi packages (cascades to packages/
-- bookable_products/node_locations/node_categories/package_itinerary_*
-- via nodes' own FK cascade, same as the admin deleteNode() helper).
delete from nodes where node_type = 'package' and slug in (
  'himmafushi-stingray-snorkeling-package',
  'himmafushi-sunset-fishing-package',
  'himmafushi-nurse-shark-point-package',
  'himmafushi-serenity-escape',
  'himmafushi-island-bliss-package',
  'himmafushi-ocean-wonders-package',
  'himmafushi-rejuvenate-explore-package',
  '4-night-himmafushi-explorer-package',
  '5-night-himmafushi-adventure-package'
);

