-- Wind Surfing is now listed as "Price on request" on the new rate card
-- (previously a fixed USD 80.50/hour) — cleared rather than left stale.
update activities set price_from = null where id = (select id from nodes where node_type = 'activity' and slug = 'himmafushi-wind-surfing');
update bookable_products set base_price = null where id = (select id from nodes where node_type = 'activity' and slug = 'himmafushi-wind-surfing');
update nodes set summary = 'Wind Surfing at Himmafushi, K. Atoll, run by Yuvi Blue Maldives. Price on request.', meta_description = 'Wind Surfing at Himmafushi, K. Atoll, run by Yuvi Blue Maldives. Price on request.' where node_type = 'activity' and slug = 'himmafushi-wind-surfing';

